package dev.slne.surf.lobby.hook.npc

import dev.slne.surf.api.core.util.toObjectSet
import dev.slne.surf.npc.api.npc.skin.NpcSkin
import dev.slne.surf.npc.api.npc.skin.NpcSkinPart

enum class SurfNpcSkins(val skinValue: String, val skinSignature: String) {
    UNKNOWN(
        "",
        ""
    ),
    SURVIVAL(
        "",
        ""
    ),
    EVENT(
        "",
        ""
    ),
    RULES(
        "",
        ""
    );

    fun getSkin() = NpcSkin(name, skinValue, skinSignature, NpcSkinPart.entries.toObjectSet())
}